from taf.converters.base import ConverterGroup
from taf.managedobject import managedobject
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class base(managedobject):
    _namespace = "converters"

    def convert(self, name):
        """
            Converts input files to output files.

            :param name: Name of the Converter alias created in previous steps.
        """
        logger.info("Converting files from " + name)
        converter = self.get_alias_value(alias=name)
        converter.convert()

    def create_converter_group(self, name, members):
        """
        Create converter group.

        :param name: Name of converter group
        :param members: comma separated name list of members of the group

        """
        logger.info("Creating Converter group " + name)
        converter_group = ConverterGroup(name=name, members=[self.get_alias_value(alias)
                                                             for alias in members.split(",")])
        self.set_alias(alias=name, obj=converter_group)
